<div class="card" style="max-width:600px"><h1>Profil Saya</h1><form wire:submit="save"><label>Nama</label><input class="input" wire:model="name"><label>Username</label><input class="input" wire:model="username"><label>Email</label><input class="input" wire:model="email"><label>Password baru (opsional)</label><input class="input" type="password" wire:model="password"><label>Konfirmasi password</label><input class="input" type="password" wire:model="password_confirmation"><label>Foto profil</label><input type="file" wire:model="photo"><button class="btn">Simpan profil</button></form></div>